classDiagram
    class TypeSystem {
        +check(expr) Type
        +infer(expr) Type
    }
    class StaticTyping {
        +checkAtCompileTime()
        +requireAnnotations()
    }
    class DynamicTyping {
        +checkAtRuntime()
        +tagValues()
    }
    class StrongTyping {
        +rejectImplicitCoercions()
    }
    class WeakTyping {
        +allowImplicitCoercions()
    }
    class TypeInference {
        +hindleyMilner()
        +localInference()
    }
    class Generics {
        +parametricPolymorphism()
        +constrainTypeParam()
    }
    TypeSystem <|-- StaticTyping
    TypeSystem <|-- DynamicTyping
    TypeSystem <|-- StrongTyping
    TypeSystem <|-- WeakTyping
    StaticTyping --> TypeInference
    StaticTyping --> Generics

classDiagram
    class Array~T~ {
        +push(item: T) void
        +pop() T
        +map~U~(fn: T--U) Array~U~
        +filter(fn: T--boolean) Array~T~
    }
    class Stack~T~ {
        -items: Array~T~
        +push(item: T) void
        +pop() T
        +peek() T
    }
    class Pair~A_B~ {
        +first: A
        +second: B
        +swap() Pair~B_A~
    }
