sections.code:
// ── Dynamic typing: JavaScript ────────────────────────────────────
let x = 42;       // x holds a number
x = 'hello';       // now x holds a string — no error
x = [1, 2, 3];    // now x holds an array — still no error

// ── Weak coercion in JavaScript ───────────────────────────────────
console.log('3' + 3);       // '33'  (number coerced to string)
console.log('3' - 1);       // 2     (string coerced to number)
console.log([] == false);   // true  (abstract equality, both coerce to 0)
console.log(null == undefined); // true (special equality rule)

// ── Simulating type checking at runtime (manual guards) ──────────
function strictAdd(a, b) {
  if (typeof a !== 'number' || typeof b !== 'number')
    throw new TypeError(`Expected numbers, got ${typeof a} and ${typeof b}`);
  return a + b;
}
console.log(strictAdd(3, 4));   // 7
try { strictAdd(3, '4'); } catch(e) { console.log(e.message); }
// Expected numbers, got number and string

// ── Type inference concepts in TypeScript (shown as JS with comments) ──
// const greeting = 'Hello';  // TS infers: string
// const count    = 0;        // TS infers: number
// const flag     = true;     // TS infers: boolean
// const nums     = [1,2,3];  // TS infers: number[]
// function double(n) { return n * 2; }  // n inferred: number (from usage)

// ── Generic-style function in JS (no static guarantee, but pattern) ──
function first(arr) {
  if (!Array.isArray(arr) || arr.length === 0)
    throw new Error('Expected non-empty array');
  return arr[0];
}
console.log(first([10, 20, 30]));   // 10
console.log(first(['a', 'b', 'c'])); // 'a'
// With TypeScript: function first<T>(arr: T[]): T — compiler ensures
// the return type matches element type at the call site.

// ── Union types (TypeScript concept, shown as JS runtime check) ──
function formatId(id) {
  // In TS: id: string | number
  if (typeof id === 'number') return `ID-${id.toFixed(0)}`;
  if (typeof id === 'string') return `ID-${id.toUpperCase()}`;
  throw new TypeError(`Invalid id type: ${typeof id}`);
}
console.log(formatId(42));     // ID-42
console.log(formatId('abc'));  // ID-ABC

// ── Type system axes illustrated ─────────────────────────────────

// 1. Static vs Dynamic
// Static  (TypeScript):  let n: number = 'hello'; // compile error
// Dynamic (JavaScript):  let n = 42; n = 'hello'; // fine at runtime

// 2. Strong vs Weak
// Strong (Python):  '3' + 3  → TypeError at runtime
// Weak   (JS):      '3' + 3  → '33'  (implicit coercion)

// 3. Type Inference
// Without inference (Java pre-generics):
//   ArrayList<String> list = new ArrayList<String>();
// With inference (Java 7+, TS, Rust):
//   var list = new ArrayList<String>();  // <String> inferred
//   const nums = [1, 2, 3];              // number[] inferred

// 4. Generics
function identity(x) { return x; }         // JS: no guarantee
// TS: function identity<T>(x: T): T { return x; }  // type-safe

// With constraint:
// function getLength<T extends { length: number }>(x: T): number {
//   return x.length;
// }
// getLength('hello');   // 5
// getLength([1,2,3]);   // 3
// getLength(42);        // ERROR: number has no .length

// 5. Structural vs Nominal typing
// TypeScript uses STRUCTURAL typing:
//   { name: string } matches any object that has a `name: string` field
//   regardless of what class it was declared as.
// Java uses NOMINAL typing:
//   class Dog and class Cat may have identical fields,
//   but they are different types — a Cat cannot be used where Dog is expected.

// ── Language/axis matrix ──────────────────────────────────────────
const matrix = [
  { lang: 'TypeScript', static: true,  strong: true,  notes: 'Structurally typed, intentionally unsound (any)' },
  { lang: 'Python',     static: false, strong: true,  notes: 'Dynamic + strong; type hints not enforced at runtime' },
  { lang: 'JavaScript', static: false, strong: false, notes: 'Dynamic + weak; notorious coercions' },
  { lang: 'Java',       static: true,  strong: true,  notes: 'Nominally typed, fully sound' },
  { lang: 'C',          static: true,  strong: false, notes: 'Static + weak; unsafe pointer casts allowed' },
  { lang: 'Rust',       static: true,  strong: true,  notes: 'Static + strong + sound (no null, no UB in safe code)' }
];
console.table(matrix.map(({ lang, static: s, strong, notes }) =>
  ({ Language: lang, Static: s, Strong: strong, Notes: notes })));
